import{_ as n,o as r,c as s,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Mahnungen aus dem Halbjahreszeugnis übernehmen","description":"","frontmatter":{"title":"Mahnungen aus dem Halbjahreszeugnis übernehmen","source_pageid":343,"source_revision":6302},"headers":[],"relativePath":"zeugnisse/vorbereitung/mahnungen-automatisch-setzen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/mahnungen-automatisch-setzen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),t={name:"zeugnisse/vorbereitung/mahnungen-automatisch-setzen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function i(u,e,g,h,o,d){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="mahnungen-aus-dem-halbjahreszeugnis-ubernehmen" tabindex="-1">Mahnungen aus dem Halbjahreszeugnis übernehmen <a class="header-anchor" href="#mahnungen-aus-dem-halbjahreszeugnis-ubernehmen" aria-label="Permalink to &quot;Mahnungen aus dem Halbjahreszeugnis übernehmen&quot;">​</a></h1><p>Lassen Sie im zweiten Halbjahr die Mahnkennzeichen aus mangelhaften oder ungenügenden Leistungen des vorherigen Halbjahreszeugnisses setzen.</p><p>Dieser Gruppenprozess ermöglicht das automatische Setzen der Mahnungen bei der ausgewählten Schülermenge. Er wird nur im zweiten Halbjahr angeboten, da er sich auf die Noten des Halbjahreszeugnisses bezieht.</p><p><strong>Mahnungen aus den vorhandenen Noten setzen</strong></p><p>Wird der Gruppenprozess angestoßen, erscheint eine Abfrage, ob die Mahnungen automatisch aufgrund mangelhafter Noten im letzten Halbjahreszeugnis gesetzt werden sollen.</p><p>Nach der Bestätigung werden die Leistungsdaten durchsucht und beim betreffenden Schüler wird bei den Fächern mit <em>mangelhaften</em> oder <em>ungenügenden</em> Leistungen ein Häkchen in der Spalte &quot;M&quot;, für Mahnung, gesetzt. Das Häkchen wird grün unterlegt, da die Mahnung den Erziehungsberechtigten durch das Zeugnis bereits mitgeteilt wurde.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Mahnungen_automatisch_setzen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6302.</p>',8)])])}const l=n(t,[["render",i]]);export{p as __pageData,l as default};
